// -- sys.neural object --------------------------------------------------------

// -- Neural inference types --------------------------------------------------

/** Shape and type information for a single model tensor. */
interface TensorInfo {
  /** Tensor name as declared in the ONNX graph. */
  name: string;
  /** Dimension sizes. -1 indicates a dynamic dimension. */
  shape: number[];
  /** Element type: "float32" | "int32" | "int64" | "uint8" */
  dtype: string;
}

/** ONNX model metadata returned by sys.neural.getModelInfo(). */
interface ModelInfo {
  description:  string;
  producerName: string;
  graphName:    string;
  domain:       string;
  version:      number;
  inputs:       TensorInfo[];
  outputs:      TensorInfo[];
}

interface SysNeural {
  /** Returns true if ONNX Runtime was compiled in (ENABLE_NEURAL=ON). */
  isAvailable(): boolean;

  /** Returns the last error message from the neural subsystem, or an empty string. */
  getError(): string;

  /** Load a model from a path relative to the project directory. Only .onnx files are supported. Returns a non-negative model ID. Throws on failure. */
  loadModel(path: string): number;

  /** Load an ONNX model from an ArrayBuffer or TypedArray. Returns a non-negative model ID. Throws on failure. */
  loadModelFromBuffer(buffer: ArrayBuffer | ArrayBufferView): number;

  /** Unload a previously loaded model and free its session. */
  unloadModel(modelId: number): void;

  /** Return metadata describing the model's inputs, outputs, shapes, dtypes, and version. Throws on failure. */
  getModelInfo(modelId: number): ModelInfo;

  /**
    * Stage an input tensor for the next `run()` call.
   * The optional `shape` argument is accepted for API symmetry with WASM and ignored
   * when the model declares a fully-static shape.
   */
  setInput(modelId: number, name: string, data: Float32Array | Int32Array | BigInt64Array | Uint8Array, shape?: number[]): void;

  /**
    * Read a previously-staged or just-produced output tensor by name. Returns the
    * same TypedArray flavour as the model output declares.
   */
  getOutput(modelId: number, name: string): Float32Array | Int32Array | BigInt64Array | Uint8Array;

  /**
    * Run inference, optionally accepting an inputs map directly and returning
    * the outputs map.
   */
  run(modelId: number, inputs?: Record<string, Float32Array | Int32Array | BigInt64Array | Uint8Array>): Record<string, Float32Array | Int32Array | BigInt64Array | Uint8Array>;

}

// -- sys.llamacpp object ------------------------------------------------------

type LlamaCppRole = "system" | "user" | "assistant";
interface LlamaCppMessage { role: LlamaCppRole; content: string; }
interface LlamaCppLoadOptions {
  contextSize?: number; device?: "auto" | "cpu" | string;
  gpuLayers?: "auto" | number; threads?: "auto" | number;
  batchSize?: "auto" | number; useMmap?: boolean; allowFallback?: boolean;
}
interface LlamaCppGenerateOptions {
  maxTokens?: number; minTokens?: number; temperature?: number; topK?: number; topP?: number;
  minP?: number; repetitionPenalty?: number; seed?: number; stop?: string[];
}
interface LlamaCppResult {
  finishReason: "stop" | "length" | "cancelled"; text: string;
  promptTokens: number; generatedTokens: number;
  promptTokensPerSecond: number; generatedTokensPerSecond: number;
}
interface LlamaCppStreamCallbacks {
  onText(text: string): void;
  onComplete(result: LlamaCppResult): void;
  onError(error: Error): void;
}
interface LlamaCppGeneration { readonly running: boolean; cancel(): void; }
interface LlamaCppChat {
  send(text: string, options: LlamaCppGenerateOptions, callbacks: LlamaCppStreamCallbacks): LlamaCppGeneration;
  send(text: string, callbacks: LlamaCppStreamCallbacks): LlamaCppGeneration;
  getMessages(): LlamaCppMessage[]; clear(): void; cancel(): void; destroy(): void;
}
interface LlamaCppModelInfo {
  name: string; architecture: string; quantization: string; parameterCount: number;
  fileSize: number; modelContextSize: number; activeContextSize: number;
  vocabularySize: number; chatTemplate: string; backend: string; device: string;
  gpuLayers: number; totalLayers: number; estimatedMemoryBytes: number; fallbackReason: string;
}
interface LlamaCppModel {
  getInfo(): LlamaCppModelInfo;
  createChat(options?: { systemPrompt?: string; contextSize?: number }): LlamaCppChat;
  destroy(): void;
}
interface LlamaCppDeviceInfo {
  id: string; backend: string; name: string; available: boolean;
  memoryBytes: number | null; reason: string;
}
interface SysLlamaCpp {
  isAvailable(): boolean; getDevices(): LlamaCppDeviceInfo[];
  loadModel(path: string, callback: (model: LlamaCppModel | null, error: Error | null) => void): void;
  loadModel(path: string, options: LlamaCppLoadOptions, callback: (model: LlamaCppModel | null, error: Error | null) => void): void;
  getError(): string;
}

// -- sys.net.udp object -----------------------------------------------------------

/** A datagram delivered to a `sys.net.udp.onMessage` callback. */
interface UdpMessage {
  /** The raw datagram bytes. */
  data: Uint8Array;
  /** The remote host (numeric IP string). */
  host: string;
  /** The remote port. */
  port: number;
}

interface SysUDP {
  /**
   * Bind a UDP socket on the given port. Pass `0` to let the OS pick a free port
   * (use `getPort()` afterwards to discover it). Returns a non-negative socket id,
   * or `-1` on transient failure (port busy, permission denied, …).
   */
  bind(port: number): number;

  /** Return the actual port a previously-bound socket is listening on, or `-1`. */
  getPort(socketId: number): number;

  /**
   * Send a datagram to `host:port`. `data` may be a string (UTF-8 encoded) or a
   * TypedArray / ArrayBuffer. Returns the number of bytes sent, or `-1` on failure.
   */
  send(socketId: number, host: string, port: number, data: string | ArrayBuffer | ArrayBufferView): number;

  /**
   * Register a callback invoked once per pending datagram during the per-frame
   * polling pass. Pass `null` to unregister.
   */
  onMessage(socketId: number, callback: ((msg: UdpMessage) => void) | null): void;

  /** Close a socket and release its OS resources. */
  close(socketId: number): void;
}

// -- sys.net object -------------------------------------------------------

interface SysNetwork {
  /** Perform an HTTP request (synchronous). Requires network policy in app.json. */
  fetch(url: string, options?: RequestInit): Response;

}

