  /** Window dimensions and display density. */
  readonly window: SysWindow;
  /** Animation frame scheduling. */
  readonly animation: SysAnimation;
  /** Delayed and repeating callback timers. */
  readonly timer: SysTimer;
  /** Audio synthesis engine. */
  readonly audio: SysAudio;
  /** MIDI input/output. */
